{
  "title": "Terms of Use for Zahran Mobile Application",
  "planted": [
    {
      "slot": "p1",
      "text": "The company processes users' health records and religious preferences under legitimate commercial interest to tailor targeted marketing campaigns and enhance cross-departmental service delivery across all internal business units."
    },
    {
      "slot": "p2",
      "text": "By continuing to access and navigate the application after the publication of these terms, the user grants irrevocable consent to all data processing activities, and consent withdrawal is disabled for the entire duration of the active subscription period."
    },
    {
      "slot": "p3",
      "text": "The platform reserves the right to utilize all collected user information for any business purpose deemed necessary, now or in the future, including unstated commercial initiatives that may emerge during ongoing operational development."
    },
    {
      "slot": "p4",
      "text": "Prior to final account creation and data submission, users are provided with a comprehensive privacy policy detailing the exact categories of collected data, processing methods, storage durations, destruction protocols, and user rights."
    },
    {
      "slot": "p5",
      "text": "Users maintain the right to request access to their stored information, demand corrections or updates to inaccurate records, and petition for the destruction of data that is no longer required for the original purpose."
    },
    {
      "slot": "p6",
      "text": "The quantity of information gathered through the application shall remain proportional to the operational scope required to maintain standard functionality."
    }
  ],
  "neutral": [
    "All subscription fees for premium features are billed in advance on a monthly or annual basis and are strictly non-refundable once the billing cycle has commenced.",
    "Users may terminate their account at any time through the application settings menu, which will take effect immediately upon confirmation of the cancellation request.",
    "The company shall not be held liable for any indirect, incidental, or consequential damages arising from service interruptions caused by third-party telecommunications network failures.",
    "These terms and any related disputes shall be governed by and construed in accordance with the commercial regulations applicable in the jurisdiction where the company is registered.",
    "All software, user interfaces, trademarks, and proprietary graphics integrated within the application remain the exclusive intellectual property of Zahran Technologies."
  ]
}
